def _ejecutar(orden):
    if not _disponible(orden.entidad):
        orden.cerrar("fallido", motivo="no_disponible")
        raise HTTPException(503, f"{orden.entidad} esta no_disponible: la orden no se ha enviado a HA")
    _servicio("alarm_control_panel", SERVICIO[orden.accion], orden.entidad, code=orden.codigo)
    if not _espera_estado(orden.entidad, ESTADO_ESPERADO[orden.accion], VERIFICACION_S):
        orden.cerrar("fallido", motivo="estado_no_alcanzado")
        raise HTTPException(502, f"{orden.entidad} no alcanzo el estado esperado")
    orden.cerrar("hecho")
